-- Generated by DB/Seeds/export_equinox_update.py; rerunnable DML only.

-- Equinox rank-3 parameters + five missing cultivation doctrines.

-- Existing nonempty lore and identity fields are preserved. No inventory edits.

begin;































update wf_user.my_frames set cultivation_school=case when cultivation_school is null or lower(btrim(cultivation_school)) in ('', 'nan', 'null') then 'Phantom Theater Conservatory' else cultivation_school end, cultivation_identity=case when cultivation_identity is null or lower(btrim(cultivation_identity)) in ('', 'nan', 'null') then 'Viral Rockstar' else cultivation_identity end, cultivation_art=case when cultivation_art is null or lower(btrim(cultivation_art)) in ('', 'nan', 'null') then 'Backbeat Inferno Dao of the Living Encore' else cultivation_art end, cultivation_color=case when cultivation_color is null or lower(btrim(cultivation_color)) in ('', 'nan', 'null') then '#E84B83' else cultivation_color end, cultivation_doctrine=case when cultivation_doctrine is null or lower(btrim(cultivation_doctrine)) in ('', 'nan', 'null') then 'Temple enters the Phantom Theater Conservatory carrying a stage that has learned to bite. Octavia''s Mandachord orders the battlefield into measured rhythm; Temple and Lizzie make that rhythm dangerous to obey. The Infested guitar is a living partner, and the Living Encore begins with the discipline of listening to something that can answer back. Pyrotechnics marks the floor with fire. Overdrive turns the space before the performer into the concert''s most dangerous seat. Ripper''s Wail binds survival to the rising heat of the performance, while Exalted Solo lets Lizzie speak at full voice. The backbeat is the examination: power offered to the cultivator who can strike at the right instant instead of merely striking harder. Viral Rockstar is the name of this build''s performance, not a claim that every chord inflicts Viral. Within the Conservatory, Temple holds the door between music and flame. The audience may choose whether to listen. The battlefield cannot choose whether to resonate.' else cultivation_doctrine end where my_frame_id=118 and warframe_id=228 and build_title='Viral Rockstar' and (cultivation_doctrine is null or lower(btrim(cultivation_doctrine)) in ('', 'nan', 'null'));

update wf_user.my_frames set cultivation_school=case when cultivation_school is null or lower(btrim(cultivation_school)) in ('', 'nan', 'null') then 'Cosmic Antimatter Council' else cultivation_school end, cultivation_identity=case when cultivation_identity is null or lower(btrim(cultivation_identity)) in ('', 'nan', 'null') then 'Father Time' else cultivation_identity end, cultivation_art=case when cultivation_art is null or lower(btrim(cultivation_art)) in ('', 'nan', 'null') then 'Still Hour Dao of the Riftbound Clockmaker' else cultivation_art end, cultivation_color=case when cultivation_color is null or lower(btrim(cultivation_color)) in ('', 'nan', 'null') then '#7568B8' else cultivation_color end, cultivation_doctrine=case when cultivation_doctrine is null or lower(btrim(cultivation_doctrine)) in ('', 'nan', 'null') then 'The Cosmic Antimatter Council studies the laws that decide where a battle may occur. Limbo Prime studies the boundary those laws leave unguarded. Father Time is the title of a cultivator who can make an enemy''s next moment wait, not a promise that he can unwind history. Banish moves a combatant across the threshold between the material plane and the Rift. Stasis arrests Rift-bound enemies and their projectiles, leaving their violence suspended until the clockmaker permits it to continue. Rift Surge makes that boundary contagious, extending his jurisdiction through enemies already caught within it. Cataclysm establishes a temporary chamber where the two planes meet, a clock face drawn around the battlefield with the end of its duration already approaching. The Still Hour Dao teaches exact placement and exact release. A frozen enemy is only one part of its practice; the other is ensuring that an ally still has a clear path through the encounter. Father Time measures mastery by what his companions can accomplish inside the moment he has held open.' else cultivation_doctrine end where my_frame_id=119 and warframe_id=201 and build_title='Father Time' and (cultivation_doctrine is null or lower(btrim(cultivation_doctrine)) in ('', 'nan', 'null'));

update wf_user.my_frames set cultivation_school=case when cultivation_school is null or lower(btrim(cultivation_school)) in ('', 'nan', 'null') then 'Cosmic Antimatter Council' else cultivation_school end, cultivation_identity=case when cultivation_identity is null or lower(btrim(cultivation_identity)) in ('', 'nan', 'null') then 'The Celestials' else cultivation_identity end, cultivation_art=case when cultivation_art is null or lower(btrim(cultivation_art)) in ('', 'nan', 'null') then 'Contending Constellation Dao of the Twin Heavens' else cultivation_art end, cultivation_color=case when cultivation_color is null or lower(btrim(cultivation_color)) in ('', 'nan', 'null') then '#55B6CF' else cultivation_color end, cultivation_doctrine=case when cultivation_doctrine is null or lower(btrim(cultivation_doctrine)) in ('', 'nan', 'null') then 'Sirius and Orion arrive before the Cosmic Antimatter Council as an argument with two voices and one place to stand. The Twin Heavens are not a peaceful union. Each brother presses forward, claiming the next movement of a body whose battlefield presence neither can possess alone. Their cultivation begins in that rivalry: the discipline of making a contest produce a constellation instead of a fracture. Abilities kindle Constellation Stars, turning successive acts into the pattern from which their greater force is drawn. Jade Stars and Astral Shell bear different answers to the same danger, the brothers expressing protection and celestial force through their own techniques. Where Xaku''s Three Voices find survival in a shared vessel, the Contending Constellation Dao finds momentum in a handover that never quite becomes agreement. The Celestials are named for this impossible inheritance: two heavens crossing the same sky. Their highest teaching is not that one brother must defeat the other. It is that the enemy must face everything their rivalry has set in motion.' else cultivation_doctrine end where my_frame_id=120 and warframe_id=229 and build_title='The Celestials' and (cultivation_doctrine is null or lower(btrim(cultivation_doctrine)) in ('', 'nan', 'null'));

update wf_user.my_frames set cultivation_school=case when cultivation_school is null or lower(btrim(cultivation_school)) in ('', 'nan', 'null') then 'Tidal Abyss Confraternity' else cultivation_school end, cultivation_identity=case when cultivation_identity is null or lower(btrim(cultivation_identity)) in ('', 'nan', 'null') then 'Ice Queen' else cultivation_identity end, cultivation_art=case when cultivation_art is null or lower(btrim(cultivation_art)) in ('', 'nan', 'null') then 'Winter Gale Dao of the Dancing Iceblade' else cultivation_art end, cultivation_color=case when cultivation_color is null or lower(btrim(cultivation_color)) in ('', 'nan', 'null') then '#A4DDEB' else cultivation_color end, cultivation_doctrine=case when cultivation_doctrine is null or lower(btrim(cultivation_doctrine)) in ('', 'nan', 'null') then 'The Tidal Abyss Confraternity knows winter in more than one posture. Frost Prime makes it a throne: a place of shelter and arrested motion. Narin carries it on the edge of a rapier. Her Winter Gale Dao begins where stillness becomes movement again, ice carried through the field with the precision of a blade finding its opening. Every advance joins cold to swordplay; every defense belongs to the same flowing practice. The Ice Queen''s crown is the clear space she earns around herself, and her court travels with her. She does not borrow the Snow Monarch''s fortress or diminish its teaching. She answers a different question: how does winter defend those who cannot afford to remain behind a wall? Through timing, a cutting wind, and the discipline to keep moving while the enemy loses the freedom to follow. In the Confraternity''s lineage, the Dancing Iceblade is the mobile sister-art of enduring frost: the same season, carried by a different sovereign.' else cultivation_doctrine end where my_frame_id=121 and warframe_id=234 and build_title='Ice Queen' and (cultivation_doctrine is null or lower(btrim(cultivation_doctrine)) in ('', 'nan', 'null'));

update wf_user.my_frames set cultivation_school=case when cultivation_school is null or lower(btrim(cultivation_school)) in ('', 'nan', 'null') then 'Cosmic Antimatter Council' else cultivation_school end, cultivation_identity=case when cultivation_identity is null or lower(btrim(cultivation_identity)) in ('', 'nan', 'null') then 'Eternal Sun' else cultivation_identity end, cultivation_art=case when cultivation_art is null or lower(btrim(cultivation_art)) in ('', 'nan', 'null') then 'Twilight Meridian Dao of the Unsetting Sun' else cultivation_art end, cultivation_color=case when cultivation_color is null or lower(btrim(cultivation_color)) in ('', 'nan', 'null') then '#D8AD62' else cultivation_color end, cultivation_doctrine=case when cultivation_doctrine is null or lower(btrim(cultivation_doctrine)) in ('', 'nan', 'null') then 'Equinox Prime takes her seat in the Cosmic Antimatter Council at the line where day becomes night. Eternal Sun is her chosen title, but the Twilight Meridian Dao permits no disciple to mistake a preference for wholeness. Metamorphosis carries her across that line, exchanging the protection of Night for the force and movement of Day. Rest quiets the battlefield; Rage opens enemies to greater harm at the cost of greater frenzy. Pacify lessens the violence around her, while Provoke lends strength to those who fight beside her. Mend gathers the means to restore. Maim gathers the consequence of lives already spent and returns it as a cutting reckoning. These are paired disciplines, each requiring a different decision about what the next moment needs. Her kinship with the Adolla Pyric School lies in radiance, but her home is the Council: her subject is the relation between opposing states. The Unsetting Sun endures because its cultivator understands the night she can become.' else cultivation_doctrine end where my_frame_id=122 and warframe_id=186 and build_title='Eternal Sun' and (cultivation_doctrine is null or lower(btrim(cultivation_doctrine)) in ('', 'nan', 'null'));

commit;

-- Verify after applying:

select my_frame_id, build_title, cultivation_school, cultivation_art from wf_user.my_frames where my_frame_id between 118 and 122 order by my_frame_id;

select a.ability_name, count(p.*) from wf_base.ability_catalog a join wf_base.ability_parameters p using (ability_catalog_id) where a.ability_name in ('Metamorphosis','Rest & Rage','Pacify & Provoke','Mend & Maim') group by a.ability_name;
